'use client';

/**
 * <RoxyLocationSearch data={...} /> — City search input with debounced /location/search calls.
 *
 * You own this file. Customize freely. The underlying Lit element loads
 * from jsDelivr at runtime via @roxyapi/ui-react, so updates ship without
 * a re-install.
 *
 * Typical wiring (server-side fetch, client-side render):
 *
 * ```ts
 * // app/api/location-search/route.ts
 * import { createRoxy } from '@roxyapi/sdk';
 * const roxy = createRoxy(process.env.ROXY_API_KEY!);
 * export async function POST(req: Request) {
 *   // <RoxyLocationSearch> calls /location/search directly. No server route
   *   // needed unless you want to proxy.
 *   return Response.json(data);
 * }
 * ```
 *
 * Theme via --roxy-* CSS custom properties on :root (see globals.css).
 */
import { RoxyLocationSearch as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyLocationSearchProps = ComponentProps<typeof Element>;

export function RoxyLocationSearch(props: RoxyLocationSearchProps) {
	return <Element {...props} />;
}

export default RoxyLocationSearch;
